<?php
declare(strict_types=1);
require_once __DIR__.'/opportunity-agents.php';
/** First-party scheduled research. No browser or external worker credential is created. */
final class LifeOpportunityRuntime {
 public function __construct(private LifeAyoOS $os,private mixed $clock=null,private mixed $transport=null){new LifeOpportunityAgents($os,$clock);$os->store->db->exec(file_get_contents(__DIR__.'/migrations/opportunity-runtime.sql'));}
 private function now():int{return$this->clock?($this->clock)():time();}private function at(?int$t=null):string{return gmdate('Y-m-d\TH:i:s\Z',$t??$this->now());}
 private function row():array{$q=$this->os->store->db->prepare('SELECT * FROM life_opportunity_runtime WHERE tenant_id=?');$q->execute([$this->os->store->tenantId]);return$q->fetch(PDO::FETCH_ASSOC)?:[];}
 public function handleOwner(string$action,array$args):array{LifeAyoOS::requireWorkspace($args,$this->os->store->tenantId);$action=preg_replace('/^ayo-os\.agents\.runtime\./','',$action);$db=$this->os->store->db;$id=$this->os->store->tenantId;$r=$this->row();if($action==='enable'){if(($args['confirm']??false)!==true||($args['confirmWrites']??false)!==true||($args['confirmProvider']??false)!==true)throw new LifeError('Approve free AI research and limited tracking writes before enabling.',403);$expires=$this->at($this->now()+90*86400);if($r)$db->prepare('UPDATE life_opportunity_runtime SET enabled=1,expires_at=?,last_error=? WHERE tenant_id=?')->execute([$expires,'',$id]);else$db->prepare('INSERT INTO life_opportunity_runtime VALUES (?,1,?,?,?,?)')->execute([$id,$expires,'','','']);}elseif($action==='disable'){if(($args['confirm']??false)!==true)throw new LifeError('Confirm stopping background research.',403);$db->prepare('UPDATE life_opportunity_runtime SET enabled=0 WHERE tenant_id=?')->execute([$id]);}elseif($action!=='status')throw new LifeError('Runtime action unavailable.');$r=$this->row();$day=(new DateTimeImmutable('@'.$this->now()))->setTimezone(new DateTimeZone('Africa/Lagos'))->format('Y-m-d');$q=$db->prepare('SELECT reserved FROM life_opportunity_agent_budget WHERE tenant_id=? AND day=?');$q->execute([$id,$day]);return['enabled'=>!empty($r['enabled'])&&($r['expires_at']??'')>$this->at(),'expiresAt'=>$r['expires_at']??'','heartbeat'=>$r['heartbeat']??'','lastRun'=>$r['last_run']??'','lastError'=>$r['last_error']??'','dailyCount'=>(int)$q->fetchColumn(),'dailyLimit'=>25,'runtime'=>'hostinger-cron','privateContextEnabled'=>false];}
 public function run():array{$db=$this->os->store->db;$id=$this->os->store->tenantId;$status=$this->handleOwner('status',['workspaceId'=>$id]);if(!$status['enabled'])return['status'=>'disabled'];$db->prepare('UPDATE life_opportunity_runtime SET heartbeat=?,last_error=? WHERE tenant_id=?')->execute([$this->at(),'',$id]);$token=bin2hex(random_bytes(32));$hash=hash('sha256',$token);$authorization='Bearer '.$token;$db->prepare('INSERT INTO life_opportunity_agent_tokens VALUES (?,?,?,?,?,?)')->execute([$hash,$id,$this->at(),$this->at($this->now()+300),'','']);$permissions=['research:claim','research:execute','daily:queue','company:write','contact:write','research:write','opportunity:write'];$db->prepare('INSERT INTO life_opportunity_agent_permissions VALUES (?,?)')->execute([$hash,json_encode($permissions,JSON_THROW_ON_ERROR)]);
 try{$access=new LifeOpportunityAgentAccess($this->os,$this->clock,$this->transport);$hour=(int)(new DateTimeImmutable('@'.$this->now()))->setTimezone(new DateTimeZone('Africa/Lagos'))->format('G');if($hour>=9){$pending=$db->prepare('SELECT COUNT(*) FROM life_opportunity_agent_jobs WHERE tenant_id=? AND status IN (?,?)');$pending->execute([$id,'queued','leased']);if((int)$pending->fetchColumn()<=15)$access->daily($authorization);}$jobs=(new LifeOpportunityAgents($this->os,$this->clock))->poll($authorization,['limit'=>1])['jobs'];if(!$jobs)return['status'=>'idle'];$job=$jobs[0];$policy=LifeOpportunityAgentAccess::jobPolicy($db,$job['id']);if(($policy['usePrivateContext']??false)===true)throw new LifeError('Selected private context needs approval for this first-party runtime.',403);$result=$access->execute($authorization,['jobId'=>$job['id'],'leaseToken'=>$job['leaseToken']]);if($result['status']==='completed'&&($policy['autoApply']??false)===true&&$this->handleOwner('status',['workspaceId'=>$id])['enabled'])$access->apply($authorization,['jobId'=>$job['id']]);$error=$result['status']==='failed'?mb_substr($result['error']??'Research unavailable.',0,300):'';$db->prepare('UPDATE life_opportunity_runtime SET last_run=?,last_error=? WHERE tenant_id=?')->execute([$this->at(),$error,$id]);return['status'=>$result['status'],'jobId'=>$job['id']];}catch(Throwable$e){$message=$e instanceof LifeError?mb_substr($e->getMessage(),0,300):'Background research needs attention.';$db->prepare('UPDATE life_opportunity_runtime SET last_run=?,last_error=? WHERE tenant_id=?')->execute([$this->at(),$message,$id]);return['status'=>'failed'];}finally{$db->prepare('DELETE FROM life_opportunity_agent_permissions WHERE token_hash=?')->execute([$hash]);$db->prepare('DELETE FROM life_opportunity_agent_tokens WHERE token_hash=?')->execute([$hash]);}}
}
